// Loads the engine fixtures generated by tests/tools/web_fixtures.cpp (ctest checks they are
// current: unit.web_fixtures_current).

import { readFileSync } from 'node:fs';
import type { ComparisonDoc, SimulationReport } from '../src/engine/report';

export interface EventJson {
  schema: 'ccsim.events/1';
  seq: number;
  op: 'R' | 'W';
  address: string;
  line: string;
  offset: number;
  l1: { result: string; set: number; tag: string; way: number };
  l2: { result: string; set: number; tag: string; way: number };
  actions: { kind: string; level: string; hit: boolean; dirty: boolean; from_policy: boolean; set: number; way: number; line: string }[];
  latency_cycles: number;
}

export interface GridJson {
  states: number[];
  tags: string[];
}

export interface Scenario {
  scenario: string;
  trace: string;
  accesses: number;
  config_words: number[];
  event_words: number[];
  events_json: EventJson[];
  grids: { l1: GridJson; l2: GridJson | null }[];
  report: SimulationReport;
}

export const SCENARIOS = [
  'demo_a_direct', 'demo_a_2way', 'demo_b', 'demo_b_write_through', 'demo_b_no_write_allocate',
  'demo_b_inclusive', 'demo_b_exclusive', 'demo_c_fifo3', 'demo_c_fifo4',
] as const;

const read = (name: string) => readFileSync(new URL(`./fixtures/${name}`, import.meta.url), 'utf8');

export const scenario = (name: (typeof SCENARIOS)[number]): Scenario => JSON.parse(read(`${name}.json`)) as Scenario;
export const comparison = (name: 'demo_a' | 'demo_c'): ComparisonDoc => JSON.parse(read(`${name}.compare.json`)) as ComparisonDoc;
export const comparisonCsv = (name: 'demo_a' | 'demo_c'): string => read(`${name}.compare.csv`);
